function validate([words, pattern]) {
  if (typeof pattern !== 'string' || pattern.length < 1 || pattern.length > 20 || !/^[a-z]+$/.test(pattern)) return 'pattern needs 1 to 20 lowercase letters.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 50) return 'words needs 1 to 50 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length !== pattern.length) return 'Every word must be as long as pattern.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase letters only.';
  }
  return null;
}

