function findAndReplacePattern(words, pattern) {
  const result = [];
  for (const word of words) {
    const toWord = new Map();
    const toPattern = new Map();
    let fits = true;
    for (let i = 0; i < pattern.length && fits; i++) {
      const p = pattern[i];
      const w = word[i];
      if (!toWord.has(p) && !toPattern.has(w)) {
        toWord.set(p, w);
        toPattern.set(w, p);
      } else if (toWord.get(p) !== w || toPattern.get(w) !== p) {
        fits = false;
      }
    }
    if (fits) {
      result.push(word);
    }
  }
  return result;
}

