function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  const large = size === 'large';
  const length = large ? 20 : pick(1, 5);
  const alphabet = large ? pick(2, 26) : pick(1, 4);
  const randomWord = () => Array.from({ length }, () => letters[pick(0, alphabet - 1)]).join('');
  const pattern = randomWord();
  const count = large ? 50 : pick(1, 7);
  const words = [];
  for (let k = 0; k < count; k++) {
    const mode = rand();
    if (mode < 0.4) {
      // Rename the pattern's letters with a random permutation: always fits.
      const perm = letters.split('');
      for (let i = perm.length - 1; i > 0; i--) { const j = pick(0, i); [perm[i], perm[j]] = [perm[j], perm[i]]; }
      words.push(pattern.split('').map(c => perm[letters.indexOf(c)]).join(''));
    } else if (mode < 0.7 && words.length > 0) {
      // Copy an earlier word and change one letter: often breaks the fit.
      const chars = words[pick(0, words.length - 1)].split('');
      chars[pick(0, length - 1)] = letters[pick(0, Math.min(alphabet, 25))];
      words.push(chars.join(''));
    } else {
      words.push(randomWord());
    }
  }
  return [words, pattern];
}
